// The store is mocked with StoreMock, generated by moq from the Store interface (see router.go). A test sets
// only the methods it expects to be called; calling any other one panics, so unexpected store use fails loudly.
//
// Table tests hold one of these constructors per row and call it in the loop, so every subtest gets a
// fresh mock with its own recorded calls.

// noStore is for requests that must never reach the store: every method is unset, so any call panics.
func noStore() *StoreMock { return &StoreMock{} }

func pingReturns(err error) func() *StoreMock {
	return func() *StoreMock {
		return &StoreMock{PingFunc: func(context.Context) error { return err }}
	}
}

func findHotelReturns(h store.Hotel, err error) func() *StoreMock {
	return func() *StoreMock {
		return &StoreMock{FindHotelByNameFunc: func(context.Context, string) (store.Hotel, error) { return h, err }}
	}
}

func findRoomsReturns(rooms []store.Room, err error) func() *StoreMock {
	return func() *StoreMock {
		return &StoreMock{FindRoomsFunc: func(context.Context, store.RoomFilter) ([]store.Room, error) { return rooms, err }}
	}
}

func createBookingReturns(b store.BookingDetails, err error) func() *StoreMock {
	return func() *StoreMock {
		return &StoreMock{CreateBookingFunc: func(context.Context, store.NewBooking) (store.BookingDetails, error) { return b, err }}
	}
}

func getBookingReturns(b store.BookingDetails, err error) func() *StoreMock {
	return func() *StoreMock {
		return &StoreMock{GetBookingFunc: func(context.Context, uuid.UUID) (store.BookingDetails, error) { return b, err }}
	}
}

// testToday is the fixed "today" for handler tests.
var testToday = time.Date(2026, 10, 26, 15, 0, 0, 0, time.UTC)

// newTestServer returns the handlers backed by st, with "today" fixed to testToday. Handler tests call
// its methods directly with a request struct and compare the response struct.
func newTestServer(st Store) *Server {
	return &Server{store: st, now: func() time.Time { return testToday }}
}

// assertResponse fails unless a handler returned wantErr (matched with errors.Is), or no error and a
// response equal to want.
func assertResponse(t *testing.T, got any, gotErr error, want any, wantErr error) {
	t.Helper()
	if wantErr != nil {
		if !errors.Is(gotErr, wantErr) {
			t.Fatalf("want error %v, got %v (response %+v)", wantErr, gotErr, got)
		}
		return
	}
	if gotErr != nil {
		t.Fatalf("unexpected error: %v", gotErr)
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("response\n got %#v\nwant %#v", got, want)
	}
}

// serve sends one request through a router backed by st, as a client would: tests using it give
// the request as strings and check the response body as a JSON string.
func serve(t *testing.T, st Store, method, target, body string) *httptest.ResponseRecorder {
	t.Helper()
	rec := httptest.NewRecorder()
	newRouter(newTestServer(st)).ServeHTTP(rec, newRequest(t, method, target, body))
	return rec
}

func newRequest(t *testing.T, method, target, body string) *http.Request {
	var r io.Reader
	if body != "" {
		r = strings.NewReader(body)
	}
	return httptest.NewRequestWithContext(t.Context(), method, target, r)
}

func apiDate(s string) *openapi_types.Date {
	return &openapi_types.Date{Time: date(s)}
}

func date(s string) time.Time {
	d, err := time.Parse(time.DateOnly, s)
	if err != nil {
		panic(err)
	}
	return d
}

// testRef is the reference of testBooking.
const testRef = "3f2b8c1e-9a4d-4c6e-b1f0-7d2e5a9c4b13"

var testReference = uuid.MustParse(testRef)

var (
	testRoom    = store.Room{ID: 2, HotelID: 1, Number: "102", Type: store.RoomTypeSingle, Capacity: 1, HotelName: "The Grand Hotel"}
	testBooking = store.BookingDetails{
		Booking: store.Booking{
			Reference: testReference, RoomID: 2, GuestName: "Jane Doe", Guests: 1,
			CheckIn: date("2027-01-11"), CheckOut: date("2027-01-13"),
			CreatedAt: time.Date(2026, 10, 26, 15, 0, 0, 0, time.UTC),
		},
		Room: testRoom,
	}

	// The API values the handlers should return for testRoom and testBooking.
	apiTestRoom = Room{
		Id: 2, Number: "102", Type: Single, Capacity: 1,
		Hotel: Hotel{Id: 1, Name: "The Grand Hotel"},
	}
	apiTestBooking = Booking{
		Reference: testReference, GuestName: "Jane Doe", Guests: 1,
		CheckIn: *apiDate("2027-01-11"), CheckOut: *apiDate("2027-01-13"),
		CreatedAt: time.Date(2026, 10, 26, 15, 0, 0, 0, time.UTC),
		Room:      apiTestRoom,
	}

	errStore = errors.New("connection refused")
)

// newValidBooking returns a new valid booking request. Tests that need an invalid one change a field of it.
func newValidBooking() BookingRequest {
	return BookingRequest{
		RoomId: 2, GuestName: "Jane Doe", Guests: 1,
		CheckIn: *apiDate("2027-01-11"), CheckOut: *apiDate("2027-01-13"),
	}
}

// The JSON a client should receive for testRoom and testBooking.
const (
	testRoomJSON    = `{"id":2,"number":"102","type":"single","capacity":1,"hotel":{"id":1,"name":"The Grand Hotel"}}`
	testBookingJSON = `{"reference":"` + testRef + `","guest_name":"Jane Doe","guests":1,` +
		`"check_in":"2027-01-11","check_out":"2027-01-13","created_at":"2026-10-26T15:00:00Z","room":` + testRoomJSON + `}`
)

// assertJSON fails unless rec has the wanted status and a JSON body equal to want. Both are parsed
// before comparing, so field order and whitespace don't matter but every name, value and format does.
func assertJSON(t *testing.T, rec *httptest.ResponseRecorder, wantStatus int, want string) {
	t.Helper()
	if rec.Code != wantStatus {
		t.Fatalf("status = %d, want %d; body %s", rec.Code, wantStatus, rec.Body)
	}
	if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("Content-Type = %q, want application/json", ct)
	}
	var got, wantV any
	if err := json.Unmarshal(rec.Body.Bytes(), &got); err != nil {
		t.Fatalf("body isn't JSON: %v; body %s", err, rec.Body)
	}
	if err := json.Unmarshal([]byte(want), &wantV); err != nil {
		t.Fatalf("bad want JSON in test: %v", err)
	}
	if !reflect.DeepEqual(got, wantV) {
		t.Fatalf("body\n got %s\nwant %s", strings.TrimSpace(rec.Body.String()), want)
	}
}
